<?php declare(strict_types=1); $type=$_GET['type']??'';$slug=$_GET['slug']??'';$allowed=['blog','research','resource','case-study'];if(!in_array($type,$allowed,true)||!preg_match('/^[a-z0-9-]+$/',$slug)){http_response_code(404);exit('Not found');}$path=__DIR__.'/data/runtime/content.json';$data=is_file($path)?json_decode((string)file_get_contents($path),true):[];$item=null;foreach(($data['items']??[]) as $x){if(($x['type']??'')===$type&&($x['slug']??'')===$slug&&($x['status']??'')==='published'){$item=$x;break;}}if(!$item){http_response_code(404);exit('Not found');}function h($v){return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}$seo=is_array($item['seo']??null)?$item['seo']:[];$title=$seo['title']??$item['title'];$desc=$seo['description']??$item['dek']??'';$canonical=$seo['canonical']??('https://cybertechintelligence.com/'.($type==='case-study'?'case-studies':$type).'/'.$slug);$schema=['@context'=>'https://schema.org','@type'=>$type==='blog'?'BlogPosting':($type==='case-study'?'Article':'Report'),'headline'=>$item['title'],'description'=>$desc,'datePublished'=>$item['publishedAt']??null,'dateModified'=>$item['updatedAt']??null,'author'=>['@type'=>'Organization','name'=>$item['author']??'CyberTech Intelligence'],'publisher'=>['@type'=>'Organization','name'=>'CyberTech Intelligence','url'=>'https://cybertechintelligence.com']];?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($title)?> | CyberTech Intelligence</title><meta name="description" content="<?=h($desc)?>"><link rel="canonical" href="<?=h($canonical)?>"><meta property="og:type" content="article"><meta property="og:title" content="<?=h($title)?>"><meta property="og:description" content="<?=h($desc)?>"><meta property="og:url" content="<?=h($canonical)?>"><meta name="twitter:card" content="summary_large_image"><script type="application/ld+json"><?=json_encode($schema,JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP)?></script><style>body{margin:0;background:#0b0d10;color:#f5f7fa;font:16px/1.7 system-ui,sans-serif}main{max-width:880px;margin:auto;padding:70px 24px}a,.meta{color:#21e6e6}h1{font-size:clamp(42px,7vw,72px);line-height:1.04}.dek{font-size:20px;color:#aeb6c2}.body{white-space:pre-wrap}</style></head><body><main><p><a href="/<?=h($type==='case-study'?'case-studies':$type)?>.html">← Back</a></p><p class="meta"><?=h(strtoupper($item['category']??$type))?></p><h1><?=h($item['title'])?></h1><p class="dek"><?=h($item['dek']??'')?></p><article class="body"><?=h($item['body']??'')?></article></main></body></html>